public int minimumAbsoluteDifference(int[] arr) {
    int best = Integer.MAX_VALUE;
    for (int i = 0; i < arr.length; i++) {
        for (int j = i + 1; j < arr.length; j++) {
            best = Math.min(best, Math.abs(arr[i] - arr[j]));
        }
    }
    return best;
}

