public int minimumAbsoluteDifference(int[] arr) {
    Arrays.sort(arr);
    int best = Integer.MAX_VALUE;
    for (int i = 1; i < arr.length; i++) {
        best = Math.min(best, arr[i] - arr[i - 1]);
    }
    return best;
}

